positions_2 = [(3, 9), (4, 8), (5, 7), (6, 6), (7, 5), (7, 7)]

# Show a small window around each 2
for r, c in positions_2:
    print(f"\nPosition ({r}, {c}):")
    # Show 3x3 area centered on the position
    for dr in range(-2, 3):
        row_idx = r + dr
        for dc in range(-2, 3):
            col_idx = c + dc
            if 0 <= row_idx < len(grid) and 0 <= col_idx < len(grid[0]):
                val = grid[row_idx][col_idx]
                marker = "*" if row_idx == r and col_idx == c else "."
                if marker == "*":
                    print(f"{marker} {val}", end="")
                else:
                    print(f"{val}{marker}" if marker == "*" else f"{val}", end="")
            else:
                print(" ", end="")
        print()

